@strawberry.type
class Query:
    @strawberry.field
    async def active_door_passcode(self, info: Info, lock_id: str) -> Optional[PasscodeType]:
        user = info.context.get("current_user")
        if not user:
            raise HTTPException(status_code=401, detail="Authentication required")

        loader: DataLoader = info.context["passcode_loader"]
        cred = await loader.load(lock_id)
        if not cred:
            return None

        if cred.assigned_user_id != user.id and not user.is_property_manager:
            raise HTTPException(status_code=403, detail="Forbidden: unauthorized to retrieve door lock PIN")

        return PasscodeType(
            lock_id=cred.lock_id,
            door_pin=cred.current_pin_code,
            expires_at=cred.expiration_time
        )
